#include <iostream>
#include <string>
using namespace std;

struct Record {
    string name;
    int amount;
};

int main() {
    int a1 = 0;
    int a2 = 0;
    int a3 = 0;
    cin >> a1 >> a2 >> a3;

    Record book[3];
    book[0].name = "猫粮";
    book[0].amount = a1;
    book[1].name = "小鱼干";
    book[1].amount = a2;
    book[2].name = "猫窝";
    book[2].amount = a3;

    for (int i = 0; i < 3; i++) {
        cout << book[i].name << " " << book[i].amount << endl;
    }
    return 0;
}
